/**
 * M11 library: every official resource that quotes clinical points becomes a claim, so the
 * review checklists cover it. Status follows how the source was read: full text or abstract →
 * sourced (the points were read there); a model summary → from-memory until someone reads it.
 */
CLAIMS.push(
  ...OFFICIAL_RESOURCES.filter((r) => r.keyPoints && r.keyPoints.length > 0).map(
    (r): ClinicalClaim => ({
      id: `m11-${r.id}`,
      module: 'M11',
      claim: `${r.title} (${r.year}) — ${r.keyPoints!.join(' · ')}`,
      location: 'src/standards/officialResources.ts',
      status: r.reading === 'texte intégral' || r.reading === 'résumé' ? 'sourced' : 'from-memory',
      source: `${r.body}${r.citation ? `. ${r.citation}` : ''}. ${r.url} (${r.reading})`,
      note: r.reading === 'résumé' ? 'Abstract only: points limited to what the abstract states.' : r.reading === 'synthèse' ? 'Only a model summary was read: check against the document.' : undefined,
    })
  )
);

export function claimsForModule(tab: string): ClinicalClaim[] {
  const tags = tab === 'M1_M2' ? ['M1', 'M2'] : [tab];
  return CLAIMS.filter((c) => tags.includes(c.module));
}

export function statusCounts(claims: ClinicalClaim[]): Record<ClaimStatus, number> {
  const out: Record<ClaimStatus, number> = { sourced: 0, 'from-memory': 0, illustrative: 0 };
  for (const c of claims) out[c.status]++;
  return out;
}
